	@Test
	public void createReadTxnBlocksWhenPoolIsExhausted(@TempDir Path dataDir) throws Exception {
		long env = openEnv(dataDir, TxnManager.POOL_SIZE);
		TxnManager txnManager = new TxnManager(env, TxnManager.Mode.RESET);
		TxnManager.Txn[] txns = new TxnManager.Txn[TxnManager.POOL_SIZE];
		CountDownLatch started = new CountDownLatch(1);
		CountDownLatch acquired = new CountDownLatch(1);
		AtomicReference<TxnManager.Txn> blockedTxn = new AtomicReference<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread waiter = new Thread(() -> {
			started.countDown();
			try {
				TxnManager.Txn txn = txnManager.createReadTxn();
				blockedTxn.set(txn);
				acquired.countDown();
			} catch (Throwable t) {
				failure.set(t);
				acquired.countDown();
			}
		}, "txn-manager-pool-waiter");

		try {
			for (int i = 0; i < txns.length; i++) {
				System.out.println("Acquiring txn " + i);
				txns[i] = txnManager.createReadTxn();
				System.out.println("Acquired txn " + i + ": " + txns[i].get());
			}

			waiter.start();

			assertTrue(started.await(5, TimeUnit.SECONDS), "Waiter thread should start");
			assertFalse(acquired.await(200, TimeUnit.MILLISECONDS),
					"Requesting more than the pool size should block until a transaction is returned");

			txns[0].close();

			assertTrue(acquired.await(5, TimeUnit.SECONDS),
					"Blocked reader should resume once a transaction is returned to the pool");
			assertTrue(failure.get() == null, () -> "Unexpected failure: " + failure.get());
			assertTrue(blockedTxn.get() != null, "Blocked reader should receive a transaction");
		} finally {
			if (blockedTxn.get() != null) {
				blockedTxn.get().close();
			}
			for (int i = 1; i < txns.length; i++) {
				if (txns[i] != null) {
					txns[i].close();
				}
			}
			waiter.join(TimeUnit.SECONDS.toMillis(5));
			mdb_env_close(env);
		}
	}

	@Test
	public void readersFullRetryDoesNotAbortTrackedInactiveTxn(@TempDir Path dataDir) throws Exception {
		long env = openEnv(dataDir, 2);
		long rawTxn1 = 0;
		TxnManager.Txn trackedTxn = null;
		TxnManager.Txn extraTxn = null;

		try {
			TxnManager txnManager = new TxnManager(env, TxnManager.Mode.RESET);
			trackedTxn = txnManager.createReadTxn();
			long trackedHandle = trackedTxn.get();

			txnManager.deactivate();
			rawTxn1 = beginReadTxn(env);

			try {
				extraTxn = txnManager.createReadTxn();
			} catch (IOException exception) {
				assertTrue(exception.getMessage().contains("MDB_READERS_FULL"), exception.getMessage());
			}
			assertEquals(trackedHandle, trackedTxn.get(),
					"Reader recovery must not abort an inactive transaction that is still owned by a live caller");
		} finally {
			if (extraTxn != null) {
				extraTxn.close();
			}
			if (trackedTxn != null) {
				trackedTxn.close();
			}
			if (rawTxn1 != 0) {
				mdb_txn_abort(rawTxn1);
			}
			mdb_env_close(env);
		}
	}

	@Test
	public void resetDoesNotAbortTrackedInactiveTxn(@TempDir Path dataDir) throws Exception {
		long env = openEnv(dataDir, 2);
		TxnManager.Txn trackedTxn = null;

		try {
			TxnManager txnManager = new TxnManager(env, TxnManager.Mode.RESET);
			trackedTxn = txnManager.createReadTxn();
			long trackedHandle = trackedTxn.get();

			txnManager.deactivate();
			txnManager.reset();

			assertEquals(trackedHandle, trackedTxn.get(),
					"Reset must not abort an inactive transaction that is still owned by a live caller");
		} finally {
			if (trackedTxn != null) {
				trackedTxn.close();
			}
			mdb_env_close(env);
		}
	}

	@Test
	public void resetSkipsUntrackedReadTxn(@TempDir Path dataDir) throws Exception {
		long env = openEnv(dataDir, 2);
		TxnManager.Txn trackedTxn = null;
		TxnManager.Txn untrackedTxn = null;

		try {
			TxnManager txnManager = new TxnManager(env, TxnManager.Mode.RESET);
			trackedTxn = txnManager.createReadTxn();
			untrackedTxn = txnManager.createReadTxnUntracked();
			long trackedVersion = trackedTxn.version();
			long version = untrackedTxn.version();

			txnManager.reset();

			assertEquals(trackedVersion + 1, trackedTxn.version(),
					"Reset must still renew regular tracked transactions");
			assertEquals(version, untrackedTxn.version(),
					"Reset must not renew untracked transactions owned by long-running refresh readers");
		} finally {
			if (trackedTxn != null) {
				trackedTxn.close();
			}
			if (untrackedTxn != null) {
				untrackedTxn.close();
			}
			mdb_env_close(env);
		}
	}

	@Test
	public void untrackedReadTxnParticipatesInActivateDeactivate(@TempDir Path dataDir) throws Exception {
		long env = openEnv(dataDir, 2);
		TxnManager.Txn untrackedTxn = null;

		try {
			TxnManager txnManager = new TxnManager(env, TxnManager.Mode.RESET);
			untrackedTxn = txnManager.createReadTxnUntracked();
			long version = untrackedTxn.version();

			txnManager.deactivate();
			txnManager.activate();

			assertEquals(version + 1, untrackedTxn.version(),
					"Untracked transactions must still renew when the environment is reactivated after map resize");
		} finally {
			if (untrackedTxn != null) {
				untrackedTxn.close();
			}
			mdb_env_close(env);
		}
	}

	private static long openEnv(Path dataDir, int maxReaders) throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_env_create(pp));
			long env = pp.get(0);
			E(mdb_env_set_maxreaders(env, maxReaders));
			E(mdb_env_open(env, dataDir.toAbsolutePath().toString(), MDB_NOTLS | MDB_NOSYNC | MDB_NOMETASYNC, 0664));
			return env;
		}
	}

	private static long beginReadTxn(long env) throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_txn_begin(env, NULL, MDB_RDONLY, pp));
			return pp.get(0);
		}
	}
